public class Main {
    public static long potongDiskon(long harga, int persen) {
        return harga - harga * persen / 100;
    }

    public static long tambahPpn(long harga) {
        return harga + harga * 12 / 100;
    }

    public static void main(String[] args) {
        long harga = 200_000;
        long setelahDiskon = potongDiskon(harga, 10);
        long hargaAkhir = tambahPpn(setelahDiskon);
        System.out.println("Harga awal     : " + harga);
        System.out.println("Setelah diskon : " + setelahDiskon);
        System.out.println("Setelah PPN    : " + hargaAkhir);
    }
}

