public class Main {
    public static long gajiBersih(long gajiPokok) {
        long potonganBpjs = gajiPokok * 4 / 100;
        long pajak = gajiPokok * 5 / 100;
        return gajiPokok - potonganBpjs - pajak;
    }

    public static void main(String[] args) {
        long gajiSari = gajiBersih(6_000_000);
        long gajiBudi = gajiBersih(8_500_000);
        System.out.println("Gaji bersih Sari: " + gajiSari);
        System.out.println("Gaji bersih Budi: " + gajiBudi);
        // potonganBpjs dan pajak tidak dikenal di sini
    }
}

