        // 4. for-each: menelusuri setiap huruf tanpa indeks
        //    toCharArray() memecah teks menjadi deretan huruf (array, dibahas di modul berikutnya)
        for (char huruf : "KOPI".toCharArray()) {
            System.out.println("for-each: " + huruf);
        }

        // 5. bersarang: loop di dalam loop
        for (int baris = 1; baris <= 2; baris++) {
            String isi = "";
            for (int kolom = 1; kolom <= 3; kolom++) {
                isi += (baris * kolom) + " ";
            }
            System.out.println("nested: " + isi.trim());
        }

        // 6. break: keluar dari loop lebih awal
        String hasil = "";
        for (int i = 1; i <= 10; i++) {
            if (i == 4) break;
            hasil += i + " ";
        }
        System.out.println("break: " + hasil.trim());

        // 7. continue: lewati sisa badan untuk putaran ini saja
        hasil = "";
        for (int i = 1; i <= 6; i++) {
            if (i % 2 == 0) continue;
            hasil += i + " ";
        }
        System.out.println("continue: " + hasil.trim());
    }
}

