        int[][] cache = new int[5][];
        for (int i = 0; i < cache.length; i++) {
            cache[i] = new int[1_000_000];   // sekitar 4 MB per array
        }
        System.out.println("Array di cache: " + cache.length + " (sekitar " + cache.length * 4 + " MB tertahan)");

        int dilepas = 0;
        for (int i = 0; i < cache.length; i++) {
            cache[i] = null;                 // referensi dilepas, GC boleh membersihkan
