        private final String ke;
        private final String subjek;
        private final boolean penting;

        private Pesan(Builder b) {
            ke = b.ke;
            subjek = b.subjek;
            penting = b.penting;
        }

        @Override
        public String toString() {
            return (penting ? "[PENTING] " : "") + subjek + " -> " + ke;
        }

        static class Builder {
            private final String ke;
            private String subjek = "(tanpa subjek)";
            private boolean penting;

            Builder(String ke) { this.ke = ke; }
            Builder subjek(String s) { subjek = s; return this; }
            Builder prioritas(boolean p) { penting = p; return this; }
            Pesan build() { return new Pesan(this); }
        }
    }

    public static void main(String[] args) {
        Pesan p = new Pesan.Builder("sari@contoh.id").subjek("Invoice").prioritas(true).build();
        System.out.println(p);
        System.out.println(new Pesan.Builder("budi@contoh.id").build());
